-- Employment episodes retain one employee identity and immutable earlier payroll.
INSERT INTO el_policies(kind,rules,reason) VALUES('rehire','[["hiring"],["payroll"]]','Independent hiring and compensation review before a new employment episode');
CREATE TABLE ops_rehire_proposals(document_id INTEGER PRIMARY KEY REFERENCES el_documents(id),departure_id INTEGER NOT NULL REFERENCES el_documents(id),term_id INTEGER NOT NULL UNIQUE REFERENCES employee_terms(id));
CREATE TABLE ops_rehires(document_id INTEGER PRIMARY KEY REFERENCES el_documents(id),departure_id INTEGER NOT NULL UNIQUE REFERENCES el_documents(id),employee_id INTEGER NOT NULL REFERENCES employees(id),start_date TEXT NOT NULL,profile_id INTEGER NOT NULL REFERENCES hr_profiles(id),access_enabled INTEGER NOT NULL CHECK(access_enabled IN(0,1)));
CREATE TABLE ops_revocations(departure_id INTEGER PRIMARY KEY REFERENCES el_documents(id),employee_id INTEGER NOT NULL REFERENCES employees(id),user_id INTEGER REFERENCES users(id),date TEXT NOT NULL);
CREATE TABLE ops_policy_formulas(document_id INTEGER PRIMARY KEY REFERENCES el_documents(id),jurisdiction TEXT NOT NULL,formulas TEXT NOT NULL,agreement TEXT NOT NULL);
CREATE TABLE ops_final_calculations(request_id INTEGER PRIMARY KEY REFERENCES el_final_requests(id),inputs_encrypted TEXT NOT NULL,fingerprint TEXT NOT NULL);
CREATE TABLE ops_setup_runs(id INTEGER PRIMARY KEY,configuration TEXT NOT NULL,reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ops_retention_rules(id INTEGER PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('candidate','review','employee_document','employment')),days INTEGER NOT NULL CHECK(days BETWEEN 1 AND 36500),effective_date TEXT NOT NULL,legal_basis TEXT NOT NULL,automatic INTEGER NOT NULL CHECK(automatic IN(0,1)),creator_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ops_retention_approvals(rule_id INTEGER PRIMARY KEY REFERENCES ops_retention_rules(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE ops_holds(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,record_id INTEGER NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ops_retention_runs(id INTEGER PRIMARY KEY,actor_id INTEGER NOT NULL REFERENCES users(id),date TEXT NOT NULL,automatic INTEGER NOT NULL CHECK(automatic IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ops_erasures(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,record_id INTEGER NOT NULL,rule_id INTEGER NOT NULL REFERENCES ops_retention_rules(id),run_id INTEGER NOT NULL REFERENCES ops_retention_runs(id),summary TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 0,UNIQUE(kind,record_id,generation));
-- Permits exist only inside a purge transaction, and only permit approved PII columns.
CREATE TABLE ops_erasure_permits(table_name TEXT NOT NULL,row_id INTEGER NOT NULL,run_id INTEGER NOT NULL REFERENCES ops_retention_runs(id),PRIMARY KEY(table_name,row_id));
CREATE TABLE ops_connections(id INTEGER PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('scim','calendar')),name TEXT NOT NULL UNIQUE,endpoint TEXT NOT NULL,secret_encrypted TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE ops_provider_checks(id INTEGER PRIMARY KEY,connection_id INTEGER REFERENCES ops_connections(id),kind TEXT NOT NULL,ok INTEGER NOT NULL CHECK(ok IN(0,1)),detail TEXT NOT NULL,config_hash TEXT NOT NULL DEFAULT '',actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ops_provider_jobs(id INTEGER PRIMARY KEY,connection_id INTEGER NOT NULL REFERENCES ops_connections(id),event_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,payload_encrypted TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN('queued','sending','sent','failed')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',external_id TEXT,completed_at TEXT);
CREATE TABLE ops_provider_identities(connection_id INTEGER NOT NULL REFERENCES ops_connections(id),employee_id INTEGER NOT NULL REFERENCES employees(id),external_id TEXT NOT NULL,episode_id INTEGER REFERENCES el_documents(id),PRIMARY KEY(connection_id,employee_id),UNIQUE(connection_id,external_id));

CREATE TABLE ops_roles(user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role='privacy_officer'),PRIMARY KEY(user_id,role));
